using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// 下一层出口 — Boss/Exit 房间清空后出现。
/// 玩家触碰后加载指定场景。
/// </summary>
[RequireComponent(typeof(Collider2D))]
public class NextLevelExit : MonoBehaviour
{
    [Tooltip("目标场景名 (在 Build Settings 中)")]
    public string nextSceneName;

    private void Awake()
    {
        var col = GetComponent<Collider2D>();
        col.isTrigger = true;
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!other.CompareTag("Player")) return;
        if (other.GetComponent<PlayerStats>() == null) return;

        if (string.IsNullOrEmpty(nextSceneName))
        {
            Debug.LogWarning("NextLevelExit: nextSceneName 为空");
            return;
        }

        if (!Application.CanStreamedLevelBeLoaded(nextSceneName))
        {
            Debug.LogError($"场景 '{nextSceneName}' 未在 Build Settings 中添加或启用，无法加载！");
            return; // 直接返回，不会触发报错
        }

        // 确保 Player 在跨场景切换时不被销毁 (与 PlayerManager 协同工作)
        DontDestroyOnLoad(other.gameObject);

        SceneManager.LoadScene(nextSceneName);
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// 侵蚀二选一弹窗：时停后显示"吞噬"和"同化"两个选项。
/// 吞噬 → 打开技能夺取弹窗（SkillStealPopupManager）
/// 同化 → 将敌人转化为随从
/// </summary>
public class ErodeChoicePopupManager : MonoBehaviour
{
    public static ErodeChoicePopupManager Instance { get; private set; }

    [Header("弹窗 UI（预制体中预设）")]
    [SerializeField] private GameObject _backdrop;
    [SerializeField] private GameObject _popupPanel;
    [SerializeField] private Text _titleText;
    [SerializeField] private Button _devourButton;
    [SerializeField] private Text _devourText;
    [SerializeField] private Button _assimilateButton;
    [SerializeField] private Text _assimilateText;
    [SerializeField] private Button _cancelButton;
    [SerializeField] private Text _cancelText;

    private Font _runtimeFont;

    // 状态
    private EnemyCore _targetEnemy;
    private IReadOnlyList<SkillInstance> _enemySkills;
    private PlayerSkillManager _playerSkillManager;
    private Action _onClose;
    private bool _isShowing;

    private void Awake()
    {
        if (Instance == null)
            Instance = this;
        else
            Destroy(gameObject);

        _runtimeFont = Font.CreateDynamicFontFromOSFont("Arial", 16);

        if (_backdrop != null)
            _backdrop.SetActive(false);
        if (_popupPanel != null)
            _popupPanel.SetActive(false);
    }

    private void OnDestroy()
    {
        if (Instance == this)
            Instance = null;
    }

    /// <summary>
    /// 显示二选一弹窗。
    /// </summary>
    /// <param name="enemy">被命中的敌人</param>
    /// <param name="hasSkills">敌人是否有技能（无技能时吞噬按钮禁用）</param>
    /// <param name="enemySkills">敌人技能列表</param>
    /// <param name="player">玩家技能管理器</param>
    /// <param name="onClose">关闭回调</param>
    public void ShowPopup(EnemyCore enemy, bool hasSkills, IReadOnlyList<SkillInstance> enemySkills,
        PlayerSkillManager player, Action onClose)
    {
        if (_isShowing) return;
        _isShowing = true;

        _targetEnemy = enemy;
        _enemySkills = enemySkills;
        _playerSkillManager = player;
        _onClose = onClose;

        if (_popupPanel == null) { _isShowing = false; return; }

        // 标题
        if (_titleText != null)
        {
            _titleText.font = _runtimeFont;
            _titleText.text = "选择行动";
        }

        // 吞噬按钮
        if (_devourButton != null)
        {
            _devourButton.onClick.RemoveAllListeners();
            _devourButton.onClick.AddListener(OnDevour);
            _devourButton.interactable = hasSkills;
        }
        if (_devourText != null)
        {
            _devourText.font = _runtimeFont;
            _devourText.text = hasSkills ? "吞噬" : "吞噬（无技能）";
        }

        // 同化按钮
        if (_assimilateButton != null)
        {
            _assimilateButton.onClick.RemoveAllListeners();
            _assimilateButton.onClick.AddListener(OnAssimilate);
            _assimilateButton.interactable = !_targetEnemy.IsDead;
        }
        if (_assimilateText != null)
        {
            _assimilateText.font = _runtimeFont;
            _assimilateText.text = "同化";
        }

        // 取消按钮
        if (_cancelButton != null)
        {
            _cancelButton.onClick.RemoveAllListeners();
            _cancelButton.onClick.AddListener(ClosePopup);
        }
        if (_cancelText != null)
            _cancelText.font = _runtimeFont;

        // 显示
        if (_backdrop != null)
            _backdrop.SetActive(true);
        _popupPanel.SetActive(true);
    }

    private void OnDevour()
    {
        HideUI();

        SkillStealPopupManager popup = SkillStealPopupManager.Instance;
        if (popup != null && _enemySkills != null && _enemySkills.Count > 0)
        {
            popup.ShowPopup(_enemySkills, _playerSkillManager, () =>
            {
                // 技能夺取弹窗关闭 → 恢复时间
                _onClose?.Invoke();
                _onClose = null;
                _isShowing = false;
            });
        }
        else
        {
            // 无弹窗或无技能 → 直接关闭
            _onClose?.Invoke();
            _onClose = null;
            _isShowing = false;
        }
    }

    private void OnAssimilate()
    {
        HideUI();

        if (_targetEnemy != null && !_targetEnemy.IsDead && _playerSkillManager != null)
        {
            _targetEnemy.Assimilate(_playerSkillManager.CasterTransform);
        }

        _onClose?.Invoke();
        _onClose = null;
        _isShowing = false;
    }

    private void HideUI()
    {
        if (_backdrop != null)
            _backdrop.SetActive(false);
        if (_popupPanel != null)
            _popupPanel.SetActive(false);
    }

    public void ClosePopup()
    {
        if (!_isShowing) return;
        _isShowing = false;

        HideUI();

        _onClose?.Invoke();
        _onClose = null;
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// 侵蚀技能夺取弹窗 — 全局暂停时显示敌人技能列表，供玩家选择夺取/升级。
/// UI 结构由预制体预设；运行时只动态填充技能槽。
/// </summary>
public class SkillStealPopupManager : MonoBehaviour
{
    public static SkillStealPopupManager Instance { get; private set; }

    [Header("预制体")]
    [SerializeField] private SkillSlotView _slotPrefab;

    [Header("弹窗 UI（预制体中预设）")]
    [SerializeField] private GameObject _backdrop;
    [SerializeField] private GameObject _popupPanel;
    [SerializeField] private Transform _slotContainer;
    [SerializeField] private Text _titleText;
    [SerializeField] private Text _cancelText;
    [SerializeField] private Button _cancelButton;

    private Font _runtimeFont;
    private IReadOnlyList<SkillInstance> _enemySkills;
    private PlayerSkillManager _playerSkillManager;
    private Action _onClose;
    private bool _isShowing;

    private void Awake()
    {
        if (Instance == null)
            Instance = this;
        else
            Destroy(gameObject);

        // 动态字体无法被预制体序列化，运行时创建
        _runtimeFont = Font.CreateDynamicFontFromOSFont("Arial", 16);

        if (_backdrop != null)
            _backdrop.SetActive(false);
        if (_popupPanel != null)
            _popupPanel.SetActive(false);
    }

    private void OnDestroy()
    {
        // 切换场景时清理单例
        if (Instance == this)
            Instance = null;
    }

    public void ShowPopup(IReadOnlyList<SkillInstance> enemySkills, PlayerSkillManager player, Action onClose)
    {
        if (_isShowing) return;
        _isShowing = true;

        _enemySkills = enemySkills;
        _playerSkillManager = player;
        _onClose = onClose;

        if (_popupPanel == null) { _isShowing = false; return; }

        if (_titleText != null)
        {
            _titleText.font = _runtimeFont;
            _titleText.text = "选择要夺取的技能";
        }

        if (_cancelText != null)
            _cancelText.font = _runtimeFont;

        // 清理旧槽位
        for (int i = _slotContainer.childCount - 1; i >= 0; i--)
            Destroy(_slotContainer.GetChild(i).gameObject);

        // 动态生成技能槽
        for (int i = 0; i < enemySkills.Count; i++)
        {
            int captured = i;
            SkillInstance enemySkill = enemySkills[i];

            SkillSlotView slotView = Instantiate(_slotPrefab, _slotContainer);

            SkillViewData viewData = BuildSlotData(enemySkill);
            slotView.Refresh(viewData);

            // 点击 = 选择该技能
            Button slotBtn = slotView.GetComponent<Button>();
            if (slotBtn == null) slotBtn = slotView.gameObject.AddComponent<Button>();
            slotBtn.onClick.RemoveAllListeners();
            slotBtn.onClick.AddListener(() => OnSkillSelected(captured));
        }

        if (_cancelButton != null)
        {
            _cancelButton.onClick.RemoveAllListeners();
            _cancelButton.onClick.AddListener(ClosePopup);
        }

        if (_backdrop != null)
            _backdrop.SetActive(true);
        _popupPanel.SetActive(true);
    }

    private SkillViewData BuildSlotData(SkillInstance skill)
    {
        SkillViewData data = default;
        if (skill == null || skill.Data == null) return data;

        SkillData def = skill.Data;
        data.Icon = def.icon;
        data.Level = skill.Level;
        data.MaxLevel = skill.MaxLevel;
        data.IsEquipped = true;
        data.IsUnlocked = true;
        data.IsCoolingDown = false;
        data.ShowKeyLabel = false;  // 弹窗中隐藏键位标签

        bool hasSkill = PlayerHasSkill(def.skillId, out int playerLv, out _);
        if (hasSkill)
            data.KeyLabel = playerLv < skill.MaxLevel ? "升级" : "已满";
        else
            data.KeyLabel = HasEmptySlot() ? "新技能" : "无空槽";

        return data;
    }

    private bool HasEmptySlot()
    {
        for (int i = 0; i < _playerSkillManager.SlotCount; i++)
            if (_playerSkillManager.IsSlotUnlocked(i) && _playerSkillManager.GetSkill(i) == null)
                return true;
        return false;
    }

    private bool PlayerHasSkill(string skillId, out int level, out int slotIdx)
    {
        for (int i = 0; i < _playerSkillManager.SlotCount; i++)
        {
            SkillInstance skill = _playerSkillManager.GetSkill(i);
            if (skill != null && skill.Data.skillId == skillId)
            {
                level = skill.Level;
                slotIdx = i;
                return true;
            }
        }
        level = 0;
        slotIdx = -1;
        return false;
    }

    private void OnSkillSelected(int index)
    {
        if (index < 0 || index >= _enemySkills.Count) return;

        SkillInstance enemySkill = _enemySkills[index];
        string skillId = enemySkill.Data.skillId;

        if (PlayerHasSkill(skillId, out int playerLv, out int slotIdx))
        {
            if (playerLv < enemySkill.MaxLevel)
                _playerSkillManager.UpgradeSkill(slotIdx);
        }
        else
        {
            _playerSkillManager.AcquireSkill(skillId);
        }

        ClosePopup();
    }

    public void ClosePopup()
    {
        if (!_isShowing) return;
        _isShowing = false;

        if (_backdrop != null)
            _backdrop.SetActive(false);
        if (_popupPanel != null)
            _popupPanel.SetActive(false);

        _onClose?.Invoke();
        _onClose = null;
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 道具详情面板 — 点击道具槽位时显示完整信息。
/// 位于 ItemPanel 旁或覆盖层。
/// </summary>
public class ItemDetailPanel : MonoBehaviour
{
    [Header("UI 元素")]
    [SerializeField] private CanvasGroup _canvasGroup;
    [SerializeField] private Image _icon;
    [SerializeField] private TMP_Text _nameText;
    [SerializeField] private TMP_Text _descText;
    [SerializeField] private Image _qualityFrame;
    [SerializeField] private Button _closeButton;

    private void Awake()
    {
        gameObject.SetActive(false);
        if (_closeButton != null)
            _closeButton.onClick.AddListener(Hide);
    }

    public void Show(ItemData item)
    {
        if (item == null) return;
        gameObject.SetActive(true);

        if (_icon != null)
        {
            _icon.sprite = item.icon;
            _icon.enabled = item.icon != null;
        }
        if (_nameText != null)
        {
            _nameText.text = item.itemName;
            _nameText.color = ItemPickup.QualityToColor(item.quality);
        }
        if (_descText != null)
            _descText.text = item.description;
        if (_qualityFrame != null)
            _qualityFrame.color = ItemPickup.QualityToColor(item.quality);
    }

    public void Hide()
    {
        gameObject.SetActive(false);
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 道具槽位 View — 纯渲染，不引用任何游戏逻辑。
/// 由 ItemPanel 管理，由 ItemUIController 调用 Refresh() 更新。
/// </summary>
public class ItemSlotView : MonoBehaviour
{
    [Header("图标")]
    [SerializeField] private Image _icon;
    [SerializeField] private GameObject _emptyIcon;

    [Header("品质框")]
    [SerializeField] private Image _qualityFrame;

    [Header("信息")]
    [SerializeField] private TMP_Text _nameText;
    [SerializeField] private TMP_Text _descText;
    [SerializeField] private TMP_Text _countText;

    [Header("Tooltip触发器")]
    [SerializeField] private Button _tooltipTrigger;

    /// <summary>当前绑定的道具数据</summary>
    public ItemData BoundItem { get; private set; }

    private void Awake()
    {
        if (_tooltipTrigger != null)
        {
            _tooltipTrigger.onClick.AddListener(() =>
                ItemPanel.Instance?.OnSlotClicked(this));
        }
    }

    public void Refresh(in ItemViewData data, ItemData boundItem)
    {
        BoundItem = boundItem;

        if (_icon != null)
        {
            _icon.sprite = data.Icon;
            _icon.enabled = data.Icon != null;
        }
        if (_emptyIcon != null)
            _emptyIcon.SetActive(data.Icon == null);

        if (_qualityFrame != null)
        {
            _qualityFrame.color = QualityToColor(data.Quality);
            _qualityFrame.gameObject.SetActive(true);
        }

        if (_nameText != null)
        {
            _nameText.text = data.Name;
            _nameText.color = QualityToColor(data.Quality);
        }

        if (_descText != null)
            _descText.text = data.Description;

        if (_countText != null)
        {
            _countText.text = data.Count > 1 ? $"x{data.Count}" : "";
            _countText.gameObject.SetActive(data.Count > 1);
        }
    }

    public void SetEmpty()
    {
        BoundItem = null;

        if (_icon != null) _icon.enabled = false;
        if (_emptyIcon != null) _emptyIcon.SetActive(true);
        if (_qualityFrame != null) _qualityFrame.gameObject.SetActive(false);
        if (_nameText != null) _nameText.text = "";
        if (_descText != null) _descText.text = "";
        if (_countText != null) _countText.text = "";
    }

    private static Color QualityToColor(ItemQuality quality) => quality switch
    {
        ItemQuality.Common    => new Color(0.78f, 0.78f, 0.78f),
        ItemQuality.Uncommon  => new Color(0.36f, 0.65f, 1f),
        ItemQuality.Rare      => new Color(0.68f, 0.36f, 1f),
        ItemQuality.Legendary => new Color(1f, 0.65f, 0.15f),
        _                     => Color.white
    };
}

